'use strict';
/**
 * clearglass-accounts/api/index.js — generated by loom/templates/system-scaffold.js
 * dispatch() is the single source both CLI and API call — one place to
 * implement real behavior, not two surfaces that quietly diverge.
 * Routes below are ordered longest-path-first — see comment in the
 * generator (system-scaffold.js) for why that ordering is load-bearing.
 */
const http = require('http');
const fs = require('fs');
const path = require('path');
const { URL } = require('url');
const { randomUUID } = require('crypto');

const PORT = parseInt(process.env.CLEARGLASS_ACCOUNTS_PORT || '7704', 10);

// cos/vaultd stores the actual session/cookie secret — encrypted, access-
// controlled, audited, already built. This system never touches raw
// credentials itself, only a vault key reference.
// §PORT COLLISION, flagged not silently worked around: cos/vaultd's own
// default is 3750, which is NEXUS copilot's port. VAULTD_PORT must be
// set to wherever vaultd actually runs once that collision is resolved —
// 3760 below is a placeholder, not a claim that vaultd runs there today.
const VAULTD_URL = process.env.VAULTD_URL || 'http://127.0.0.1:3760';
const VAULT_COMPARTMENT = 'clearglass-accounts';
const USAGE_THRESHOLD = parseFloat(process.env.ACCOUNTS_USAGE_THRESHOLD || '90');

// ── Local, disk-first store for account METADATA + usage % ─────────────
// Deliberately separate from vault: usage percentage and provider/label
// are not secrets. Only sessionRef (the actual cookie/token) goes to
// vaultd. Mirrors LOOM's own registry.js discipline — load on construct,
// write on every mutation, nothing deleted, only marked.
const DATA_DIR = process.env.CLEARGLASS_ACCOUNTS_DATA || path.join(__dirname, '..', 'data');
const ACCOUNTS_FILE = path.join(DATA_DIR, 'accounts.json');

function _load() {
  try { return JSON.parse(fs.readFileSync(ACCOUNTS_FILE, 'utf8')); }
  catch (_) { return {}; }
}
function _persist(state) {
  if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
  fs.writeFileSync(ACCOUNTS_FILE, JSON.stringify(state, null, 2));
}

// ── vaultd HTTP client — thin, honest about failure ─────────────────────
function _vaultRequest(method, vpath, body = null, timeoutMs = 5000) {
  return new Promise((resolve) => {
    const payload = body ? JSON.stringify(body) : null;
    const u = new URL(VAULTD_URL + vpath);
    const req = http.request({
      hostname: u.hostname, port: u.port, path: u.pathname + u.search, method,
      headers: { 'Content-Type': 'application/json', ...(payload ? { 'Content-Length': Buffer.byteLength(payload) } : {}) },
      timeout: timeoutMs,
    }, (res) => {
      let data = '';
      res.on('data', d => { data += d; });
      res.on('end', () => {
        try { resolve({ ok: res.statusCode < 400, status: res.statusCode, data: JSON.parse(data) }); }
        catch { resolve({ ok: false, status: res.statusCode, data: { error: 'unparseable vaultd response' } }); }
      });
    });
    req.on('error', e => resolve({ ok: false, data: { error: e.message, code: e.code, hint: 'vaultd unreachable — is it running, and on the port VAULTD_URL points at?' } }));
    req.on('timeout', () => { req.destroy(); resolve({ ok: false, data: { error: 'vaultd timeout' } }); });
    if (payload) req.write(payload);
    req.end();
  });
}

async function dispatch(opId, args) {
  const state = _load();

  switch (opId) {
    case 'accounts.list': {
      return { ok: true, op: opId, accounts: Object.values(state) };
    }

    case 'accounts.add': {
      if (!args.provider || !args.sessionRef) {
        return { ok: false, op: opId, error: 'provider and sessionRef are required' };
      }
      const id = randomUUID();
      // Store the actual secret in vaultd — this call is real, and its
      // success/failure is reported honestly, not assumed.
      const vaultResult = await _vaultRequest('POST', '/secrets', {
        compartmentName: VAULT_COMPARTMENT, key: id, value: args.sessionRef, scope: 'compartment',
      });
      if (!vaultResult.ok) {
        return { ok: false, op: opId, error: 'vaultd write failed, account NOT registered', detail: vaultResult.data };
      }
      state[id] = {
        id, provider: args.provider, label: args.label || args.provider,
        vaultKey: id, lastUsagePercent: null, lastUsageAt: null, addedAt: Date.now(),
      };
      _persist(state);
      return { ok: true, op: opId, account: state[id] };
    }

    case 'accounts.remove': {
      const acct = state[args.id];
      if (!acct) return { ok: false, op: opId, error: `no account: ${args.id}` };
      const vaultResult = await _vaultRequest('DELETE', `/secrets/${VAULT_COMPARTMENT}/${acct.vaultKey}`);
      delete state[args.id];
      _persist(state);
      return { ok: true, op: opId, removed: args.id, vaultRevoked: vaultResult.ok };
    }

    case 'accounts.usage': {
      const acct = state[args.id];
      if (!acct) return { ok: false, op: opId, error: `no account: ${args.id}` };
      return { ok: true, op: opId, id: args.id, usagePercent: acct.lastUsagePercent, lastUsageAt: acct.lastUsageAt };
    }

    case 'accounts.usage-report': {
      const acct = state[args.id];
      if (!acct) return { ok: false, op: opId, error: `no account: ${args.id}` };
      const percent = parseFloat(args.percent);
      if (Number.isNaN(percent) || percent < 0 || percent > 100) {
        return { ok: false, op: opId, error: 'percent must be a number 0-100' };
      }
      acct.lastUsagePercent = percent;
      acct.lastUsageAt = Date.now();
      acct.lastUsageSource = args.source || 'unknown';
      _persist(state);
      const overThreshold = percent >= USAGE_THRESHOLD;
      return { ok: true, op: opId, id: args.id, recorded: percent, overThreshold, threshold: USAGE_THRESHOLD };
    }

    case 'accounts.route': {
      if (!args.provider) return { ok: false, op: opId, error: 'provider is required' };
      const candidates = Object.values(state).filter(a => a.provider === args.provider);
      if (!candidates.length) {
        return { ok: false, op: opId, error: `no accounts registered for provider: ${args.provider}` };
      }
      // Prefer accounts under threshold; among those, prefer the one with
      // the lowest known usage (least-loaded). Accounts with no usage
      // data yet are treated as 0% — untested is not the same as unsafe,
      // but it also isn't preferred over a KNOWN-low account; both are
      // eligible, sorted together, lowest usage first either way.
      const eligible = candidates.filter(a => (a.lastUsagePercent ?? 0) < USAGE_THRESHOLD);
      if (!eligible.length) {
        return { ok: false, op: opId, error: `all ${candidates.length} account(s) for ${args.provider} are at or above ${USAGE_THRESHOLD}% — none available`, candidates: candidates.map(a => ({ id: a.id, usagePercent: a.lastUsagePercent })) };
      }
      eligible.sort((a, b) => (a.lastUsagePercent ?? 0) - (b.lastUsagePercent ?? 0));
      return { ok: true, op: opId, routedTo: eligible[0].id, usagePercent: eligible[0].lastUsagePercent, consideredCount: candidates.length };
    }

    default: return { ok: false, error: `unknown operation: ${opId}` };
  }
}

function createServer() {
  return http.createServer(async (req, res) => {
    const u = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    const args = Object.fromEntries(u.searchParams);
  if (req.method === 'POST' && req.url.startsWith('/api/accounts/usage-report')) {
    const result = await dispatch('accounts.usage-report', args);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(result));
    return;
  }
  if (req.method === 'GET' && req.url.startsWith('/api/accounts/usage')) {
    const result = await dispatch('accounts.usage', args);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(result));
    return;
  }
  if (req.method === 'POST' && req.url.startsWith('/api/accounts/route')) {
    const result = await dispatch('accounts.route', args);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(result));
    return;
  }
  if (req.method === 'GET' && req.url.startsWith('/api/accounts')) {
    const result = await dispatch('accounts.list', args);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(result));
    return;
  }
  if (req.method === 'POST' && req.url.startsWith('/api/accounts')) {
    const result = await dispatch('accounts.add', args);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(result));
    return;
  }
  if (req.method === 'DELETE' && req.url.startsWith('/api/accounts')) {
    const result = await dispatch('accounts.remove', args);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(result));
    return;
  }
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ ok: false, error: 'no matching route' }));
  });
}

if (require.main === module) {
  createServer().listen(PORT, () => console.log(`clearglass-accounts API on :${PORT}`));
}

module.exports = { dispatch, createServer, PORT };
